FUZZ_ASSERT(validator != nullptr, "Validator allocation failed");
bool will_fail = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
validator->operation([will_fail](std::string &in){ (void)in; return will_fail ? std::string("fail") : std::string(); });
// Give it a short name for identification
std::string vname = FUZZ_PARAM_STR(); if(vname.size() > 16) vname.resize(16);
validator->name(vname);
// Validation: validator constructed and callable set; non-null output

// Create a FormatterLambda with a benign lambda that formats a trivial string
auto fn = [](const CLI::App *a, std::string n, CLI::AppFormatMode m) -> std::string {
    (void)a; (void)m;
    if(n.size() > 32) n.resize(32);
    return std::string("fmt:") + n;
};
CLI::FormatterLambda *fl = new CLI::FormatterLambda(fn);
FUZZ_ASSERT(fl != nullptr, "FormatterLambda allocation failed");
// Validation: concrete object created with valid callable; returned non-null

