import random
import string
from typing import List

# Target data type: free-form text (UTF-8 strings) used across many stubs.
# Strategy:
# - Produce short to medium UTF-8 strings that are likely meaningful for CLI parsing/formatting paths.
# - Include variants: option-like tokens (-s, --long, /WIN:VAL), paths, quoted segments, key=value, text with spaces,
#   braces for default-flag values, numbers with units, IPv4 candidates, and mixed unicode.
# - Keep total size <= 4096 bytes. We will pack multiple lines separated by newlines so that fuzz harness
#   can slice different strings when calling FUZZ_PARAM_STR repeatedly from the same buffer.
# - Seeded randomness via the provided seed.

UNI_BLOCKS = [
    # Some safe Unicode ranges to spice inputs, still valid UTF-8
    (0x00A0, 0x00FF),   # Latin-1 supplement
    (0x0100, 0x017F),   # Latin Extended-A
    (0x0370, 0x03FF),   # Greek
    (0x0400, 0x04FF),   # Cyrillic
]

SAFE_PRINT = string.ascii_letters + string.digits + "-_"


def rand_ascii(rng: random.Random, n: int) -> str:
    return "".join(rng.choice(string.printable[:-6]) for _ in range(n))  # avoid \t,\r,\x0b,\x0c


def rand_token(rng: random.Random, min_len=1, max_len=12) -> str:
    n = rng.randint(min_len, max_len)
    return "".join(rng.choice(SAFE_PRINT) for _ in range(n))


def rand_unicode(rng: random.Random, n: int) -> str:
    out = []
    for _ in range(n):
        block = rng.choice(UNI_BLOCKS)
        cp = rng.randint(block[0], block[1])
        out.append(chr(cp))
    return "".join(out)


def opt_short(rng: random.Random) -> str:
    c = rng.choice(string.ascii_letters)
    payload = rand_token(rng, 0, 6)
    return f"-{c}{payload}"


def opt_long(rng: random.Random) -> str:
    name = rand_token(rng, 3, 12)
    if rng.random() < 0.5:
        val = rand_ascii(rng, rng.randint(0, 10))
        return f"--{name}={val}"
    return f"--{name}"


def opt_windows(rng: random.Random) -> str:
    name = rand_token(rng, 2, 10)
    if rng.random() < 0.5:
        val = rand_ascii(rng, rng.randint(0, 10))
        return f"/{name}:{val}"
    return f"/{name}"


def path_like(rng: random.Random) -> str:
    if rng.random() < 0.5:
        # Unix-like
        parts = [rand_token(rng, 1, 6) for _ in range(rng.randint(1, 4))]
        return "/" + "/".join(parts)
    # Windows-like
    drive = rng.choice(string.ascii_uppercase)
    parts = [rand_token(rng, 1, 6) for _ in range(rng.randint(1, 3))]
    return f"{drive}:/" + "/".join(parts)


def quoted(rng: random.Random) -> str:
    s = rand_ascii(rng, rng.randint(0, 24))
    if rng.random() < 0.5:
        return f'"{s}"'
    return f"'{s}'"


def key_value(rng: random.Random) -> str:
    k = rand_token(rng, 1, 10)
    v = rand_ascii(rng, rng.randint(0, 16))
    sep = rng.choice(['=', ':'])
    return f"{k}{sep}{v}"


def defaults_flag_annot(rng: random.Random) -> str:
    # Examples the library recognizes: {x}, !y, --opt={!a}
    a = rand_token(rng, 1, 6)
    b = rand_token(rng, 1, 6)
    pat = rng.choice([
        f"{{{a}}}",
        f"!{a}",
        f"--{a}={{{b}}}",
        f"--{a},!{b},{{{a}}}",
    ])
    return pat


def number_with_unit(rng: random.Random) -> str:
    num = str(rng.randint(0, 10**6))
    unit = rng.choice(["k", "K", "m", "M", "kb", "MB", "g", "GiB", "ms", "s", "B"]) if rng.random() < 0.8 else ""
    sep = "" if rng.random() < 0.7 else " "
    return f"{num}{sep}{unit}"


def ipv4_candidate(rng: random.Random) -> str:
    if rng.random() < 0.7:
        return ".".join(str(rng.randint(0, 255)) for _ in range(4))
    # malformed-but-still-text variant (validator should handle)
    return f"{rng.randint(0,999)}.{rng.randint(0,999)}.{rng.randint(0,999)}.{rng.randint(0,999)}"


def timer_title(rng: random.Random) -> str:
    style = rng.choice(["Simple", "Big", "Custom"])
    return f"{style} Timer"


def paragraph(rng: random.Random) -> str:
    words = [rand_token(rng, 1, rng.randint(3, 8)) for _ in range(rng.randint(5, 20))]
    return " ".join(words)


def mapping_like(rng: random.Random) -> str:
    # e.g., "on=1,off=0,true=1,false=0"
    pairs = [
        ("on", "1"), ("off", "0"), ("true", "1"), ("false", "0"),
        (rand_token(rng, 2, 6), str(rng.randint(0, 9)))
    ]
    rng.shuffle(pairs)
    return ",".join(f"{k}={v}" for k, v in pairs)


def section_name(rng: random.Random) -> str:
    # parent.parent.name with '.' or '/'
    sep = rng.choice(['.', '/'])
    parts = [rand_token(rng, 2, 6) for _ in range(rng.randint(1, 3))]
    return sep.join(parts)


def escaped_text(rng: random.Random) -> str:
    # Include characters that string-utils might escape
    core = rand_ascii(rng, rng.randint(4, 20))
    extras = rng.choice(["\\\"", "\\'", "\\n", "\\t", "=:\\\"", "\\\\"])  # includes =:" pattern
    return core + extras


def make_line_set(rng: random.Random) -> List[str]:
    lines: List[str] = []
    # App name/desc
    lines.append(paragraph(rng))
    lines.append(rand_token(rng, 3, 12))
    # Usage/footer/description text
    for _ in range(3):
        lines.append(paragraph(rng))
    # Option-like tokens
    for _ in range(6):
        lines.append(rng.choice([opt_short(rng), opt_long(rng), opt_windows(rng)]))
    # Paths
    for _ in range(3):
        lines.append(path_like(rng))
    # Quoted strings
    for _ in range(3):
        lines.append(quoted(rng))
    # key=value
    for _ in range(3):
        lines.append(key_value(rng))
    # Default-flag annotations
    for _ in range(3):
        lines.append(defaults_flag_annot(rng))
    # Numbers/units
    for _ in range(4):
        lines.append(number_with_unit(rng))
    # IPv4 candidates
    for _ in range(3):
        lines.append(ipv4_candidate(rng))
    # Timer titles
    for _ in range(2):
        lines.append(timer_title(rng))
    # Transformer mapping-like string
    lines.append(mapping_like(rng))
    # Section names
    for _ in range(2):
        lines.append(section_name(rng))
    # Escaped content
    for _ in range(3):
        lines.append(escaped_text(rng))
    # Some unicode lines
    for _ in range(3):
        lines.append(rand_unicode(rng, rng.randint(3, 12)))
    # Plain random ascii blobs
    for _ in range(5):
        lines.append(rand_ascii(rng, rng.randint(0, 64)).replace("\x00", ""))
    return lines


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Build multiple groups of lines to ensure sufficient supply for multiple FUZZ_PARAM_STR calls
    all_lines: List[str] = []
    groups = 1 + rng.randint(0, 2)  # 1..3 groups
    for _ in range(groups):
        all_lines.extend(make_line_set(rng))
    # Deduplicate some to add variety but keep size bounded
    if rng.random() < 0.5:
        rng.shuffle(all_lines)
    # Join with newlines; sanitize NULs; bound total size to 4096 bytes
    blob = ("\n".join(all_lines)).replace("\x00", "")
    if len(blob.encode('utf-8')) > 4096:
        # Trim by characters until under limit (simple safe approach)
        enc = blob.encode('utf-8')[:4096]
        # Ensure we do not cut in the middle of a UTF-8 sequence: backtrack to valid sequence end
        # Try decode with backoff
        for cut in range(0, 4):
            try:
                return enc[:len(enc)-cut].decode('utf-8', 'ignore').encode('utf-8')
            except Exception:
                continue
        return enc  # fallback raw bytes
    return blob.encode('utf-8')

import random
import string
from typing import List

# We generate valid command-line tokens suitable for CLI11 parsing.
# The fuzzer harness consumes FUZZ_PARAM_STR and builds argv-like arrays.
# We will emit a newline-separated sequence of tokens so that different
# FUZZ_PARAM_STR pulls can read sequential slices from the same buffer.
# Tokens avoid embedded NULs, keep moderate sizes, and include a mix of:
# - program names
# - short flags (-x, -abc, -n=5)
# - long options (--opt, --opt=value)
# - Windows-style options (/opt, /opt:value)
# - positional values (numbers, paths, words)
# - subcommand markers ("--", "--", terminators)
# This aims to exercise different Classifier paths and parse overloads.

SAFE_CHARS = string.ascii_letters + string.digits + "-_./:@+%"
WORDS = [
    "help", "version", "verbose", "quiet", "config", "path", "file", "dir",
    "list", "add", "remove", "update", "status", "init", "commit", "push",
    "pull", "clone", "run", "test", "build", "clean"
]

LONG_OPTS = [
    "help", "help-all", "version", "verbose", "quiet", "config", "config-file",
    "path", "file", "dir", "count", "name", "threads", "size", "mode",
]

SHORT_OPTS = list("abcdefghijklmnopqrstuvwxyz")

WIN_OPTS = ["help", "version", "verbose", "quiet", "config", "path", "file", "dir"]

SUBCOMMANDS = ["git", "cli11", "tool", "sub", "alpha", "beta"]

PATH_PARTS = ["usr", "var", "tmp", "home", "etc", "bin", "lib", "share", "data"]


def _rand_word(rng: random.Random, min_len=1, max_len=10) -> str:
    n = rng.randint(min_len, max_len)
    return ''.join(rng.choice(SAFE_CHARS) for _ in range(n))


def _rand_path(rng: random.Random) -> str:
    depth = rng.randint(1, 4)
    parts = [rng.choice(PATH_PARTS) for _ in range(depth-1)]
    leaf = _rand_word(rng, 1, 8)
    base = "/" + "/".join(parts + [leaf]) if parts else leaf
    # Occasionally add an extension
    if rng.random() < 0.5:
        base += "." + rng.choice(["txt", "cfg", "ini", "log", "dat"])
    return base


def _rand_number(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return str(rng.randint(-1000, 1000))
    # size-like with unit
    val = rng.randint(0, 10_000)
    unit = rng.choice(["b", "kb", "mb", "gb", "KiB", "MiB"])
    return f"{val}{unit}"


def _long_opt(rng: random.Random) -> str:
    name = rng.choice(LONG_OPTS)
    form = rng.random()
    if form < 0.34:
        return f"--{name}"
    elif form < 0.67:
        return f"--{name}={_rand_word(rng,1,8)}"
    else:
        return f"--{name}={_rand_number(rng)}"


def _short_opt(rng: random.Random) -> str:
    form = rng.random()
    if form < 0.4:
        return f"-{rng.choice(SHORT_OPTS)}"
    elif form < 0.7:
        # grouped shorts
        k = rng.randint(2, 4)
        return "-" + ''.join(rng.choice(SHORT_OPTS) for _ in range(k))
    else:
        # short with attached value using = or space (space will be separate token)
        ch = rng.choice(SHORT_OPTS)
        if rng.random() < 0.5:
            return f"-{ch}={_rand_number(rng)}"
        else:
            return f"-{ch}{rng.choice(['', ''])}"  # plain short; value may appear as next token


def _win_opt(rng: random.Random) -> str:
    name = rng.choice(WIN_OPTS)
    sep = rng.choice([':', '='])
    if rng.random() < 0.5:
        return f"/{name}"
    else:
        val = rng.choice([_rand_word(rng,1,8), _rand_number(rng), _rand_path(rng)])
        return f"/{name}{sep}{val}"


def _positional(rng: random.Random) -> str:
    choice = rng.random()
    if choice < 0.3:
        return _rand_word(rng, 3, 10)
    elif choice < 0.6:
        return _rand_path(rng)
    else:
        return _rand_number(rng)


def _special_tokens(rng: random.Random) -> List[str]:
    toks = []
    # Subcommand terminator and separators
    if rng.random() < 0.5:
        toks.append("--")
    # Possible explicit positional mark is typically "--"
    return toks


def _program_name(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return rng.choice(["prog", "app", "cli", "tool"])  # simple
    # something like path/to/prog
    return _rand_path(rng).lstrip('/') or "prog"


def _build_token_stream(rng: random.Random) -> List[str]:
    tokens: List[str] = []
    # Sometimes include a subcommand prefix
    if rng.random() < 0.4:
        tokens.append(rng.choice(SUBCOMMANDS))
    # Mix a variety of tokens
    n_groups = rng.randint(3, 8)
    for _ in range(n_groups):
        kind = rng.random()
        if kind < 0.25:
            tokens.append(_long_opt(rng))
        elif kind < 0.5:
            tokens.append(_short_opt(rng))
        elif kind < 0.65:
            tokens.append(_win_opt(rng))
        else:
            tokens.append(_positional(rng))
        # Sometimes follow options with separate value tokens
        if tokens[-1].startswith("--") and rng.random() < 0.3 and "=" not in tokens[-1]:
            tokens.append(_positional(rng))
        if tokens[-1].startswith("-") and not tokens[-1].startswith("--") and '=' not in tokens[-1] and rng.random() < 0.25:
            tokens.append(_positional(rng))
        # Occasional special tokens
        tokens.extend(_special_tokens(rng))
    return tokens


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Decide scenario pattern to cover different fuzzer consumption orders
    scenario = rng.randint(0, 3)

    tokens: List[str] = []

    # Always ensure a non-empty program name for argv[0] scenarios
    prog = _program_name(rng)

    if scenario == 0:
        # argv-style list: prog plus 1-4 args
        tokens.append(prog)
        tokens.extend(_build_token_stream(rng)[: rng.randint(1, 4)])
    elif scenario == 1:
        # A single command line string for parse(std::string,bool)
        # We still serialize as tokens; consumer slices by FUZZ_PARAM_STR
        tokens.append(' '.join([prog] + _build_token_stream(rng)))
    elif scenario == 2:
        # Vector<string> with a couple of args
        tokens.append(prog)
        tokens.extend(_build_token_stream(rng)[: rng.randint(2, 6)])
    else:
        # Stream input: "prog t1 t2"-like combined
        stream_line = ' '.join(["prog", _rand_word(rng,1,8), _positional(rng)])
        tokens.append(stream_line)
        # Provide a few extra tokens for other FUZZ_PARAM_STR calls
        tokens.extend(_build_token_stream(rng)[: rng.randint(1, 3)])

    # Sanitize tokens: replace newlines and avoid empty strings
    cleaned: List[str] = []
    for t in tokens:
        if not t:
            t = "_"
        t = t.replace('\n', '_').replace('\r', '_').replace('\x00', '_')
        cleaned.append(t)

    # Join tokens with newlines so multiple FUZZ_PARAM_STR pulls read sequential items
    data = '\n'.join(cleaned)
    # Cap size to 4096 bytes
    enc = data.encode('utf-8')[:4096]
    return enc

import random
import string
from typing import List

# This generator produces well-formed command line strings that exercise CLI11 parsing:
# - mixture of short/long/windows-style options, flags with/without values
# - positional arguments, subcommands, separators "--"
# - quoted args with spaces and escaped quotes/backslashes
# - equals-assignment and space-separated values
# - combined short flags, negative numbers, units, IPv4-like tokens, file/dir-like paths
# - optional custom delimiter scenarios for split_up
# The output is a single bytes buffer (UTF-8) of length <= 4096.

SHORT_FLAGS = list("abcde fghijklmnopqrstuvwxyz".replace(" ", ""))
LONG_NAMES = [
    "help", "version", "config", "count", "size", "path",
    "enable", "disable", "mode", "output", "input", "rate",
    "ip", "host", "port", "verbose", "quiet", "list", "name",
]
SUBCOMMANDS = ["init", "run", "test", "build", "clean", "status", "serve", "bench"]
WIN_PREFIXES = ["/", "-"]  # Windows style often uses '/'
UNITS = ["B", "KB", "MB", "GB", "KiB", "MiB", "GiB"]
BOOL_WORDS = ["true", "false", "1", "0", "yes", "no"]
MODES = ["fast", "slow", "auto", "manual", "on", "off"]

# Some values for options
FILE_PARTS = ["/etc", "/var", "/tmp", "C:/Windows", "C:/Temp", "./data", "../out"]
FILE_NAMES = ["conf.ini", "settings.toml", "input.txt", "output.bin", "image.png", "log", ".hidden"]
DIR_NAMES = ["bin", "lib", "include", "build", "Release", "Debug", "obj"]

SPACES = [" ", "\t"]


def rnd(rng: random.Random, seq):
    return rng.choice(seq)


def maybe(rng: random.Random, p: float) -> bool:
    return rng.random() < p


def rand_ipv4(rng: random.Random) -> str:
    return ".".join(str(rng.randint(0, 255)) for _ in range(4))


def rand_number_with_unit(rng: random.Random) -> str:
    n = rng.randint(0, 10_000_000)
    if maybe(rng, 0.7):
        return f"{n}{rnd(rng, UNITS)}"
    return str(n)


def rand_path(rng: random.Random) -> str:
    if maybe(rng, 0.5):
        base = rnd(rng, FILE_PARTS)
    else:
        base = "" if maybe(rng, 0.3) else "./"
    parts = []
    for _ in range(rng.randint(0, 3)):
        parts.append(rnd(rng, DIR_NAMES))
    if maybe(rng, 0.7):
        parts.append(rnd(rng, FILE_NAMES))
    p = base
    for part in parts:
        if p and not p.endswith('/') and not p.endswith('\\'):
            sep = '/' if not (p and p[1:2] == ':') else '\\'
            p += sep
        p += part
    return p or "."


def shell_escape(arg: str) -> str:
    # Quote if spaces or special characters; escape internal quotes and backslashes
    if any(c.isspace() for c in arg) or any(c in arg for c in ['"', "'", '\\', ';', '#', '[', ']']):
        # Prefer double quotes and escape backslash and double-quote
        escaped = arg.replace('\\', r'\\').replace('"', r'\"')
        return f'"{escaped}"'
    return arg


def make_short_flags(rng: random.Random) -> List[str]:
    out = []
    # generate combined short flags like -abc and with value -n10 or -n 10
    for _ in range(rng.randint(0, 3)):
        if maybe(rng, 0.6):
            k = rng.randint(2, 5)
            flags = ''.join(rng.choice(SHORT_FLAGS) for _ in range(k))
            out.append(f"-{flags}")
        else:
            flag = rng.choice(SHORT_FLAGS)
            if maybe(rng, 0.5):
                # with attached value
                if maybe(rng, 0.5):
                    val = str(rng.randint(-1000, 1000))
                    out.append(f"-{flag}{val}")
                else:
                    val = rnd(rng, [rand_number_with_unit(rng), rand_path(rng), rand_ipv4(rng), rnd(rng, MODES)])
                    out.append(f"-{flag}={val}")
            else:
                out.append(f"-{flag}")
    return out


def make_long_opts(rng: random.Random) -> List[str]:
    out = []
    for _ in range(rng.randint(1, 5)):
        name = rnd(rng, LONG_NAMES)
        form = rng.randint(0, 4)
        if form == 0:
            out.append(f"--{name}")
        elif form == 1:
            out.append(f"--{name}={shell_escape(rand_path(rng))}")
        elif form == 2:
            out.append(f"--{name}={shell_escape(rand_number_with_unit(rng))}")
        elif form == 3:
            out.append(f"--{name}={rnd(rng, BOOL_WORDS)}")
        else:
            out.append(f"--{name}={shell_escape(rnd(rng, MODES))}")
    return out


def make_windows_style(rng: random.Random) -> List[str]:
    out = []
    for _ in range(rng.randint(0, 3)):
        pref = rnd(rng, WIN_PREFIXES)
        name = rnd(rng, LONG_NAMES).replace('-', '')
        if maybe(rng, 0.5):
            out.append(f"{pref}{name}")
        else:
            sep = ':' if maybe(rng, 0.5) else '='
            val = rnd(rng, [rand_path(rng), rand_number_with_unit(rng), rnd(rng, MODES)])
            out.append(f"{pref}{name}{sep}{val}")
    return out


def make_positionals(rng: random.Random) -> List[str]:
    out = []
    for _ in range(rng.randint(0, 4)):
        choice = rng.randint(0, 6)
        if choice == 0:
            out.append(shell_escape(rand_path(rng)))
        elif choice == 1:
            out.append(rand_ipv4(rng))
        elif choice == 2:
            out.append(shell_escape("some text with spaces"))
        elif choice == 3:
            out.append(str(rng.randint(-10000, 10000)))
        elif choice == 4:
            out.append(shell_escape("name_with_underscores"))
        elif choice == 5:
            out.append(shell_escape(rng.choice(["alpha", "beta", "gamma", "delta"])) )
        else:
            out.append(shell_escape(rand_number_with_unit(rng)))
    return out


def make_subcommand_block(rng: random.Random) -> List[str]:
    out = []
    if maybe(rng, 0.6):
        sc = rnd(rng, SUBCOMMANDS)
        out.append(sc)
        # subcommand can have its own options and positionals
        out.extend(make_short_flags(rng))
        out.extend(make_long_opts(rng))
        out.extend(make_positionals(rng))
    return out


def build_command_line(rng: random.Random) -> str:
    parts: List[str] = []
    # program name
    prog = rnd(rng, ["prog", "mytool", "cli11-demo", "app.exe"])  # keep simple
    parts.append(prog)

    # mixture before subcommand
    parts.extend(make_short_flags(rng))
    parts.extend(make_windows_style(rng))

    # Sometimes add separator -- to force positionals
    if maybe(rng, 0.4):
        parts.append("--")

    parts.extend(make_long_opts(rng))

    # Optional subcommand block
    parts.extend(make_subcommand_block(rng))

    # Trailing positionals
    parts.extend(make_positionals(rng))

    # Randomly insert quotes/escaped tricky positional
    if maybe(rng, 0.4):
        tricky = 'path with spaces/' + rnd(rng, FILE_NAMES)
        parts.append(shell_escape(tricky))
    if maybe(rng, 0.3):
        parts.append(shell_escape('quoted"inner"value'))
    if maybe(rng, 0.3):
        parts.append(shell_escape('back\\slash\\heavy'))

    # Join with spaces; occasionally use tabs between some args to test whitespace handling
    pieces = []
    for i, p in enumerate(parts):
        pieces.append(p)
        if i != len(parts) - 1:
            pieces.append(rnd(rng, SPACES) if maybe(rng, 0.3) else " ")
    cmd = ''.join(pieces)

    # Ensure size bound
    if len(cmd) > 4000:
        cmd = cmd[:4000]
    return cmd


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Build either a full command line or a raw argument string for split_up
    if maybe(rng, 0.5):
        cmd = build_command_line(rng)
    else:
        # Construct a token stream focusing on quoting/brackets for split_up
        tokens = []
        for _ in range(rng.randint(3, 10)):
            kind = rng.randint(0, 5)
            if kind == 0:
                tokens.append(shell_escape("value with spaces"))
            elif kind == 1:
                tokens.append(f"[{rng.randint(1,5)},{rng.randint(6,10)}]")
            elif kind == 2:
                tokens.append(shell_escape(rand_path(rng)))
            elif kind == 3:
                tokens.append(f"--{rnd(rng, LONG_NAMES)}={str(rng.randint(0,100))}")
            elif kind == 4:
                tokens.append(rnd(rng, ["-abc", "-n10", "-v", "--"]))
            else:
                tokens.append(rand_ipv4(rng))
        sep = rnd(rng, SPACES + [",", ";"]) if maybe(rng, 0.5) else " "
        cmd = sep.join(tokens)
        if len(cmd) > 4000:
            cmd = cmd[:4000]
    return cmd.encode("utf-8")
